from datetime import date

def solve(args):
    current = date.fromisoformat(args['date'])
    return date(current.year, current.month + args['months'], current.day).isoformat()

def solve(args):
    total = sum(item['unit_minor'] * item['quantity'] for item in args['items'])
    return int(total * (1 - args['discount_bps'] / 10000))
